#!/usr/bin/env bash

###############################################################################
# @fileoverview Setup script for P2 #1539 Phase 7: Advanced Team Coordination
#
# GOV-002 COMPLIANCE
# - Deterministic: Idempotent setup with consistent initialization
# - Audited: All initialization logged with timestamps
# - Immutable: Configuration-driven via environment variables
# - Immutable Records: Setup operations recorded in audit trail
#
# SCRIPT PURPOSE
# Initializes advanced team coordination infrastructure:
# - Database schema for performance metrics
# - Kafka topics for team coordination events
# - Initial configuration for ML models
# - Service registration for coordination endpoints
# - Idempotent: safe to run multiple times
#
# USAGE
#   ./setup-advanced-team-coordination.sh [environment]
#
# ENVIRONMENTS
#   - development: Local development setup
#   - staging: Pre-production environment
#   - production: Production environment
#
# AUDIT TRAIL
# All setup operations logged to:
#   - stdout: Real-time progress
#   - .logs/setup-advanced-team-coordination.log: Persistent audit trail
#   - Kafka: team.ops.setup_events topic (when Kafka available)
#
# @author Autonomous Infrastructure
# @version 1.0.0
# @date 2026-04-26
###############################################################################

set -euo pipefail

# Color codes for output
RED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nNC='\\033[0m' # No Color

# Logging functions
log_info() {\n  echo -e \"${GREEN}[$(date +'%Y-%m-%d %H:%M:%S')]${NC} $1\"\n}\n\nlog_warn() {\n  echo -e \"${YELLOW}[$(date +'%Y-%m-%d %H:%M:%S')] WARN${NC} $1\"\n}\n\nlog_error() {\n  echo -e \"${RED}[$(date +'%Y-%m-%d %H:%M:%S')] ERROR${NC} $1\" >&2\n}\n\nlog_success() {\n  echo -e \"${GREEN}[$(date +'%Y-%m-%d %H:%M:%S')] SUCCESS${NC} $1\"\n}\n\n# Get environment\nENVIRONMENT=\"${1:-development}\"\nlog_info \"Setting up Advanced Team Coordination for environment: $ENVIRONMENT\"\n\n# Setup directories\nLOG_DIR=\".logs\"\nCONFIG_DIR=\".config/team-coordination\"\n\nmkdir -p \"$LOG_DIR\"\nmkdir -p \"$CONFIG_DIR\"\n\n# Log file\nLOG_FILE=\"$LOG_DIR/setup-advanced-team-coordination.log\"\n\n# Redirect stderr to log file while keeping stdout visible\nexec 1> >(tee -a \"$LOG_FILE\")\nexec 2> >(tee -a \"$LOG_FILE\" >&2)\n\nlog_info \"Starting Advanced Team Coordination setup\"\nlog_info \"Log file: $LOG_FILE\"\n\n# ============================================================================\n# Phase 1: Verify Dependencies\n# ============================================================================\n\nlog_info \"Phase 1: Verifying dependencies\"\n\n# Check for Node.js/npm\nif ! command -v npm &> /dev/null; then\n  log_error \"npm not found. Please install Node.js\"\n  exit 1\nfi\nlog_success \"npm found: $(npm --version)\"\n\n# Check for psql (PostgreSQL)\nif ! command -v psql &> /dev/null; then\n  log_warn \"psql not found. Database initialization will be skipped.\"\n  SKIP_DB=true\nelse\n  log_success \"psql found\"\n  SKIP_DB=false\nfi\n\n# ============================================================================\n# Phase 2: Install TypeScript Dependencies\n# ============================================================================\n\nlog_info \"Phase 2: Installing TypeScript dependencies\"\n\ncd apps/extensions/team-hub || {\n  log_error \"Failed to enter team-hub directory\"\n  exit 1\n}\n\nlog_info \"Installing npm packages\"\nif npm list uuid &> /dev/null; then\n  log_success \"uuid package already installed\"\nelse\n  npm install uuid\n  log_success \"uuid package installed\"\nfi\n\ncd - > /dev/null || exit 1\n\n# ============================================================================\n# Phase 3: Initialize Database Schema\n# ============================================================================\n\nif [ \"$SKIP_DB\" = false ]; then\n  log_info \"Phase 3: Initializing database schema\"\n  \n  # Database connection parameters\n  DB_HOST=\"${DB_HOST:-localhost}\"\n  DB_PORT=\"${DB_PORT:-5432}\"\n  DB_NAME=\"${DB_NAME:-team_coordination}\"\n  DB_USER=\"${DB_USER:-postgres}\"\n  \n  # Check database exists\n  if psql -h \"$DB_HOST\" -U \"$DB_USER\" -lqt | cut -d\\| -f 1 | grep -qw \"$DB_NAME\"; then\n    log_info \"Database $DB_NAME already exists\"\n  else\n    log_info \"Creating database $DB_NAME\"\n    createdb -h \"$DB_HOST\" -U \"$DB_USER\" \"$DB_NAME\" || log_warn \"Database creation may have failed\"\n  fi\n  \n  # Create tables for team coordination\n  log_info \"Creating tables for performance metrics\"\n  \n  psql -h \"$DB_HOST\" -U \"$DB_USER\" -d \"$DB_NAME\" << 'EOF' || log_warn \"Table creation may have failed\"\nCREATE TABLE IF NOT EXISTS individual_metrics (\n  id SERIAL PRIMARY KEY,\n  member_id VARCHAR(255) NOT NULL,\n  period_start TIMESTAMP NOT NULL,\n  period_end TIMESTAMP NOT NULL,\n  velocity INTEGER,\n  quality_score INTEGER,\n  reliability_score INTEGER,\n  collaboration_score INTEGER,\n  tasks_completed INTEGER,\n  bug_escape_rate DECIMAL(5,2),\n  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  INDEX idx_member_id (member_id),\n  INDEX idx_period (period_start, period_end)\n);\n\nCREATE TABLE IF NOT EXISTS team_metrics (\n  id SERIAL PRIMARY KEY,\n  team_id VARCHAR(255) NOT NULL,\n  period_start TIMESTAMP NOT NULL,\n  period_end TIMESTAMP NOT NULL,\n  total_velocity INTEGER,\n  quality_score INTEGER,\n  reliability_score INTEGER,\n  efficiency DECIMAL(10,2),\n  predictability DECIMAL(5,2),\n  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  INDEX idx_team_id (team_id),\n  INDEX idx_period (period_start, period_end)\n);\n\nCREATE TABLE IF NOT EXISTS performance_insights (\n  id SERIAL PRIMARY KEY,\n  insight_id VARCHAR(255) UNIQUE NOT NULL,\n  type VARCHAR(50) NOT NULL,\n  severity VARCHAR(20) NOT NULL,\n  title TEXT NOT NULL,\n  description TEXT,\n  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  INDEX idx_type_severity (type, severity)\n);\nEOF\n  \n  log_success \"Database schema initialized\"\nelse\n  log_info \"Phase 3: Skipping database initialization (psql not available)\"\nfi\n\n# ============================================================================\n# Phase 4: Create Kafka Topics\n# ============================================================================\n\nlog_info \"Phase 4: Creating Kafka topics for team coordination\"\n\n# Topics to create\nKAFKA_TOPICS=(\n  \"team.routing.decisions:3:1\"\n  \"team.capacity.forecast:3:1\"\n  \"team.workload.recommendations:3:1\"\n  \"team.performance.individual:3:1\"\n  \"team.performance.aggregate:3:1\"\n  \"team.performance.insights:3:1\"\n  \"team.ops.setup_events:1:1\"\n)\n\nif command -v kafka-topics.sh &> /dev/null; then\n  BOOTSTRAP_SERVER=\"${KAFKA_BOOTSTRAP_SERVERS:-localhost:9092}\"\n  \n  for topic_config in \"${KAFKA_TOPICS[@]}\"; do\n    IFS=':' read -r topic partitions replication <<< \"$topic_config\"\n    \n    log_info \"Creating Kafka topic: $topic\"\n    kafka-topics.sh --bootstrap-server \"$BOOTSTRAP_SERVER\" \\\n      --create --if-not-exists \\\n      --topic \"$topic\" \\\n      --partitions \"$partitions\" \\\n      --replication-factor \"$replication\" || \\\n      log_warn \"Failed to create Kafka topic: $topic\"\n  done\n  \n  log_success \"Kafka topics created\"\nelse\n  log_warn \"kafka-topics.sh not found. Skipping Kafka topic creation.\"\n  log_info \"Topics can be created manually using kafka-topics.sh\"\nfi\n\n# ============================================================================\n# Phase 5: Initialize Configuration\n# ============================================================================\n\nlog_info \"Phase 5: Initializing configuration files\"\n\n# Create ML model configuration\ncat > \"$CONFIG_DIR/ml-model-config.json\" << 'EOF'\n{\n  \"taskRouter\": {\n    \"modelVersion\": \"1.0.0\",\n    \"weights\": {\n      \"capabilityMatch\": 0.40,\n      \"availability\": 0.20,\n      \"capacity\": 0.20,\n      \"performance\": 0.15,\n      \"collaboration\": 0.05\n    },\n    \"updateInterval\": 3600\n  },\n  \"capacityForecaster\": {\n    \"modelVersion\": \"1.0.0\",\n    \"horizonDays\": 14,\n    \"confidenceIntervals\": [0.10, 0.50, 0.90],\n    \"monteCarloSimulations\": 1000\n  },\n  \"workloadBalancer\": {\n    \"modelVersion\": \"1.0.0\",\n    \"strategies\": [\"round-robin\", \"skill-based\", \"load-balanced\", \"fair-share\"],\n    \"defaultStrategy\": \"load-balanced\",\n    \"rebalanceThreshold\": 0.30\n  },\n  \"performanceTracker\": {\n    \"modelVersion\": \"1.0.0\",\n    \"metricsRetention\": 90,\n    \"insightThresholds\": {\n      \"qualityAlert\": 85,\n      \"velocityDeclinePercent\": 20,\n      \"predictabilityAlert\": 0.70\n    }\n  }\n}\nEOF\n\nlog_success \"Configuration created: $CONFIG_DIR/ml-model-config.json\"\n\n# Create environment configuration template\ncat > \"$CONFIG_DIR/team-coordination.env.example\" << 'EOF'\n# Advanced Team Coordination Configuration\n\n# Database\nDB_HOST=localhost\nDB_PORT=5432\nDB_NAME=team_coordination\nDB_USER=postgres\nDB_PASSWORD=changeme\n\n# Kafka\nKAFKA_BOOTSTRAP_SERVERS=localhost:9092\nKAFKA_TOPIC_PREFIX=team\n\n# ML Models\nML_MODEL_CONFIG_PATH=.config/team-coordination/ml-model-config.json\nML_UPDATE_INTERVAL=3600\n\n# Performance Tracking\nPERF_METRICS_RETENTION_DAYS=90\nPERF_INSIGHT_GENERATION_INTERVAL=3600\n\n# Team Coordination\nTEAM_COORDINATION_ENABLED=true\nROUTING_STRATEGY=load-balanced\nWORKLOAD_REBALANCE_THRESHOLD=0.30\n\n# Audit\nAUDIT_LOG_LEVEL=info\nAUDIT_LOG_PATH=.logs\nEOF\n\nlog_success \"Environment template created: $CONFIG_DIR/team-coordination.env.example\"\n\n# ============================================================================\n# Phase 6: Service Registration\n# ============================================================================\n\nlog_info \"Phase 6: Registering team coordination services\"\n\n# Create service endpoint registry\ncat > \"$CONFIG_DIR/service-endpoints.json\" << 'EOF'\n{\n  \"services\": [\n    {\n      \"name\": \"ml-task-router\",\n      \"version\": \"1.0.0\",\n      \"port\": 8090,\n      \"endpoints\": [\n        {\n          \"path\": \"/route\",\n          \"method\": \"POST\",\n          \"description\": \"Route a task to best team member\"\n        },\n        {\n          \"path\": \"/history\",\n          \"method\": \"GET\",\n          \"description\": \"Get routing decision history\"\n        },\n        {\n          \"path\": \"/scores/:memberId\",\n          \"method\": \"GET\",\n          \"description\": \"Get team member routing scores\"\n        }\n      ]\n    },\n    {\n      \"name\": \"capacity-forecaster\",\n      \"version\": \"1.0.0\",\n      \"port\": 8091,\n      \"endpoints\": [\n        {\n          \"path\": \"/forecast/member/:memberId\",\n          \"method\": \"GET\",\n          \"description\": \"Forecast member capacity\"\n        },\n        {\n          \"path\": \"/forecast/team\",\n          \"method\": \"GET\",\n          \"description\": \"Forecast team-wide capacity\"\n        }\n      ]\n    },\n    {\n      \"name\": \"workload-balancer\",\n      \"version\": \"1.0.0\",\n      \"port\": 8092,\n      \"endpoints\": [\n        {\n          \"path\": \"/balance\",\n          \"method\": \"POST\",\n          \"description\": \"Analyze and rebalance workload\"\n        },\n        {\n          \"path\": \"/trend\",\n          \"method\": \"GET\",\n          \"description\": \"Get workload trend analysis\"\n        }\n      ]\n    },\n    {\n      \"name\": \"team-performance-tracker\",\n      \"version\": \"1.0.0\",\n      \"port\": 8093,\n      \"endpoints\": [\n        {\n          \"path\": \"/member/:memberId\",\n          \"method\": \"GET\",\n          \"description\": \"Get member performance summary\"\n        },\n        {\n          \"path\": \"/team/:teamId\",\n          \"method\": \"GET\",\n          \"description\": \"Get team performance summary\"\n        },\n        {\n          \"path\": \"/insights\",\n          \"method\": \"GET\",\n          \"description\": \"Get performance insights\"\n        }\n      ]\n    }\n  ]\n}\nEOF\n\nlog_success \"Service endpoints registered: $CONFIG_DIR/service-endpoints.json\"\n\n# ============================================================================\n# Phase 7: Verify Setup\n# ============================================================================\n\nlog_info \"Phase 7: Verifying setup\"\n\n# Check all required files exist\nREQUIRED_FILES=(\n  \"apps/extensions/team-hub/src/ml-task-router.ts\"\n  \"apps/extensions/team-hub/src/capacity-forecaster.ts\"\n  \"apps/extensions/team-hub/src/workload-balancer.ts\"\n  \"apps/extensions/team-hub/src/team-performance-tracker.ts\"\n  \"$CONFIG_DIR/ml-model-config.json\"\n  \"$CONFIG_DIR/team-coordination.env.example\"\n  \"$CONFIG_DIR/service-endpoints.json\"\n)\n\nall_files_present=true\nfor file in \"${REQUIRED_FILES[@]}\"; do\n  if [ -f \"$file\" ]; then\n    log_success \"✓ $file\"\n  else\n    log_error \"✗ $file (MISSING)\"\n    all_files_present=false\n  fi\ndone\n\nif [ \"$all_files_present\" = true ]; then\n  log_success \"All required files present\"\nelse\n  log_error \"Some required files are missing\"\n  exit 1\nfi\n\n# ============================================================================\n# Completion\n# ============================================================================\n\nlog_success \"Advanced Team Coordination setup complete!\"\nlog_info \"\"\nlog_info \"Next steps:\"\nlog_info \"1. Review configuration: $CONFIG_DIR/ml-model-config.json\"\nlog_info \"2. Set up environment: cp $CONFIG_DIR/team-coordination.env.example .env\"\nlog_info \"3. Start services: npm run start --prefix apps/extensions/team-hub\"\nlog_info \"4. Monitor logs: tail -f $LOG_FILE\"\nlog_info \"\"\nlog_info \"Documentation: apps/extensions/team-hub/README.md\"\nlog_success \"Setup logged to: $LOG_FILE\"\n\nexit 0\n